class ToolInstaller:
    """工具安装管理器 — 串联注册表、探测、持久化与 Provider 热注册。"""

    def __init__(self, registry, db: ToolDatabase, subagent_manager=None,
                 config=None, mcp_tools=None, ws_client=None):
        """
        Args:
            registry: ToolRegistry（agent_runtime.core.tool_registry）
            db: ToolDatabase 持久化实例
            subagent_manager: SubagentManager（用于 Provider 热注册/注销）
            config: RuntimeConfig（可选，提供 tools_file/runtime_home/params）
            mcp_tools: 既有 MCP ToolRegistry（app.tools，可选，用于统一视图）
            ws_client: 平台 WS 客户端（可选，用于工具状态变更上报）
        """
        self._registry = registry
        self._db = db
        self._manager = subagent_manager
        self._config = config
        self._mcp_tools = mcp_tools
        self._ws_client = ws_client
        self._installing: set = set()      # 并发锁：正在安装/卸载的 key

    # ────────────────────────────────────────
    # 生命周期
    # ────────────────────────────────────────

    @property
    def registry(self):
        """工具注册表。"""
        return self._registry

    @property
    def db(self) -> ToolDatabase:
        """安装记录持久化实例。"""
        return self._db

    @property
    def installing(self) -> set:
        """当前正在安装/卸载的工具 key 集合。"""
        return set(self._installing)

    def set_ws_client(self, ws_client) -> None:
        """注入平台 WS 客户端（服务启动时 ws_client 晚于 installer 创建）。"""
        self._ws_client = ws_client

    async def _notify_platform(self, key: str, status: str,
                               version: Optional[str] = None,
                               healthy: Optional[bool] = None) -> None:
        """工具安装/卸载/健康状态变更时通过平台 WS 上报（协同模式）。

        未连接平台（本地模式）或上报异常时静默跳过，不影响主流程。
        """
        ws = self._ws_client
        if ws is None:
            return
        try:
            from agent_runtime.ws import protocol
            agent_id = getattr(self._config, "agent_id", None)
            msg = protocol.make_tool_status(
                agent_id, key, status, version=version, healthy=healthy)
            await ws.send(msg)
            logger.debug("工具状态已上报平台: %s -> %s", key, status)
        except Exception:
            logger.debug("工具状态 WS 上报失败: %s", key, exc_info=True)

    async def initialize(self) -> None:
        """初始化：建表 + 合并平台 tools.json（幂等，失败不阻断启动）。"""
        await self._db.initialize()
        try:
            await self.reload_platform_tools()
        except Exception:
            logger.warning("加载平台 tools.json 失败", exc_info=True)

    async def shutdown(self) -> None:
        """关闭持久化连接。"""
        try:
            await self._db.close()
        except Exception:
            logger.debug("关闭工具数据库失败", exc_info=True)

    # ─────────────────────────────────────────
    # 安装
    # ─────────────────────────────────────────

    async def install(self, key: str, version: str = None) -> InstallResult:
        """一键安装工具。

        流程：描述符校验 → 并发锁 → 落库 installing → 前置依赖检测 →
        逐条执行 install_cmds → 探测确认 → 落库结果 → Provider 热注册。

        Args:
            key: 工具 key
            version: 可选版本号（如 "22"/"20"/"18"），仅对声明了 versions 的工具生效
        """
        descriptor = self._registry.get(key)
        if not descriptor:
            return InstallResult(success=False, message=f"未知工具: {key}")

        if descriptor.is_builtin:
            return InstallResult(success=True, message="内置工具无需安装",
                                 hint=None)

        # 支持自动安装的条件：有 npm package，或者有 install_cmds + versions（如 Node.js）
        has_version_install = bool(descriptor.install_cmds and descriptor.versions)
        if not descriptor.can_auto_install and not has_version_install:
            hint = descriptor.install_hint or "该工具不支持自动安装，请参考官方文档手动安装"
            logger.info("工具 %s 不支持自动安装: %s", key, hint)
            return InstallResult(success=False, message="该工具不支持自动安装",
                                 hint=hint)

        if not descriptor.install_cmds:
            return InstallResult(success=False, message="该工具未配置安装命令",
                                 hint=descriptor.install_hint)

        if key in self._installing:
            return InstallResult(success=False, message="安装进行中，请勿重复触发")

        # 版本校验：工具声明了 versions 但未提供 version，使用第一个（最新）
        if descriptor.versions:
            if not version or version == "latest":
                version = descriptor.versions[0]
            elif version not in descriptor.versions:
                return InstallResult(
                    success=False,
                    message=f"不支持的版本 {version}，可选: {', '.join(descriptor.versions)}")

        self._installing.add(key)
        logs: list[str] = []
        try:
            await self._db.update_status(key, STATUS_INSTALLING, source=SOURCE_LOCAL)
            logger.info("开始安装工具: %s (%s) version=%s",
                        key, descriptor.package or descriptor.binary, version or '-')

            env = await self._build_subprocess_env(descriptor)

            # 前置依赖检测（使用补齐后的 PATH，确保 nvm 等用户级安装可被发现）
            missing = self._check_prerequisites(descriptor, env=env)
            if missing:
                message = f"缺少前置依赖: {', '.join(missing)}，请先安装后重试"
                logs.append(message)
                exec_log = "\n".join(logs)
                await self._db.update_status(key, STATUS_FAILED, exec_log=exec_log)
                return InstallResult(success=False, message=message, exec_log=exec_log,
                                     hint=self._prerequisite_hint(missing))

            # 逐条执行安装命令
            for index, raw_cmd in enumerate(descriptor.install_cmds, start=1):
                cmd = self._expand_placeholders(raw_cmd, version=version)
                logs.append(f"$ {cmd}")
                logger.info("[%s] 执行安装命令 %d/%d: %s",
                            key, index, len(descriptor.install_cmds), cmd)
                returncode, output = await self._run_cmd(
                    cmd, INSTALL_CMD_TIMEOUT, env)
                logs.append(output.strip() or "(无输出)")
                if returncode != 0:
                    exec_log = "\n".join(logs)
                    message = f"安装命令执行失败 (exit {returncode}): {cmd}"
                    logger.warning("[%s] %s", key, message)
                    await self._db.update_status(key, STATUS_FAILED, exec_log=exec_log)
                    return InstallResult(success=False, message=message,
                                         exec_log=exec_log,
                                         hint=self._install_failure_hint(descriptor, output))

            # 探测确认（先丢弃 PATH/探测缓存，把安装 prefix + 子进程补齐的 PATH
            # 目录一并纳入搜索，消除"安装用 A 环境、探测用 B 环境"的偏差）。
            # 安装成功判据回归为单一可靠信号 installed（二进制可定位）；--version
            # 降级为尽力而为的健康检查，用长超时 + 重试吸收冷启动/鉴权握手。
            reset_path_caches()
            invalidate_probe_cache(key)
            probe = await probe_tool(
                descriptor, timeout=PROBE_TIMEOUT_INSTALL,
                retries=INSTALL_PROBE_RETRIES, first_run_grace=True,
                extra_dirs=self._probe_extra_dirs(descriptor))
            logs.append(f"# probe: found={probe.found} installed={probe.installed} "
                        f"healthy={probe.healthy} version={probe.version} "
                        f"path={probe.path} problem={probe.problem}")
            exec_log = "\n".join(logs)

            if not probe.installed:
                message = probe.detail or \
                    f"安装命令执行成功但未定位到可执行文件（{probe.problem}）"
                await self._db.update_status(key, STATUS_FAILED,
                                             version=probe.version, exec_log=exec_log)
                await self._notify_platform(key, STATUS_FAILED,
                                            version=probe.version, healthy=False)
                return InstallResult(success=False, message=message,
                                     version=probe.version, exec_log=exec_log)

            # installed=True 即判安装成功：落库 + 热注册 Provider（用户配置
            # token 后即用）；healthy=False 只作告警，不阻断安装。
            await self._db.update_status(key, STATUS_INSTALLED,
                                         version=probe.version, exec_log=exec_log)
            logger.info("工具安装成功: %s version=%s path=%s healthy=%s",
                        key, probe.version, probe.path, probe.healthy)

            self._on_tool_installed(descriptor)

            if probe.healthy:
                message = f"{descriptor.name} 安装成功"
                hint = None
            else:
                message = f"{descriptor.name} 已安装，但 --version 未通过健康检查"
                hint = probe.detail or \
                    "已安装，但 --version 未通过，可能需要登录或配置 token"
            await self._notify_platform(key, STATUS_INSTALLED,
                                        version=probe.version,
                                        healthy=probe.healthy)
            return InstallResult(success=True, message=message,
                                 version=probe.version, exec_log=exec_log,
                                 hint=hint)

        except Exception as exc:
            logger.exception("工具安装异常: %s", key)
            logs.append(f"[异常] {type(exc).__name__}: {exc}")
            exec_log = "\n".join(logs)
            try:
                await self._db.update_status(key, STATUS_FAILED, exec_log=exec_log)
            except Exception:
                logger.debug("写入失败状态异常", exc_info=True)
            return InstallResult(success=False, message=f"安装异常: {exc}",
                                 exec_log=exec_log)
        finally:
            self._installing.discard(key)

    async def uninstall(self, key: str) -> InstallResult:
        """卸载工具。"""
        descriptor = self._registry.get(key)
        if not descriptor:
            return InstallResult(success=False, message=f"未知工具: {key}")

        if key in self._installing:
            return InstallResult(success=False, message="安装/卸载进行中，请稍后重试")

        if not descriptor.uninstall_cmds:
            return InstallResult(success=False, message="该工具未提供自动卸载命令",
                                 hint=descriptor.install_hint
                                 or "请参考官方文档手动卸载")

        # 未安装（无记录且探测不到二进制）时不执行卸载命令
        record = await self._db.get(key)
        present = await probe_tool(descriptor, use_cache=True)
        if not present.found:
            if record is None:
                return InstallResult(success=False, message="工具未安装，无需卸载")
            if record.status in (STATUS_FAILED, STATUS_UNINSTALLED):
                # 二进制已不存在且状态为失败/已卸载，直接清理记录
                await self._db.update_status(key, STATUS_UNINSTALLED,
                                             version=None, exec_log="二进制未找到，直接清除记录")
                self._on_tool_uninstalled(descriptor)
                logger.info("工具记录已清除（二进制未找到）: %s", key)
                return InstallResult(success=True, message=f"{descriptor.name} 记录已清除",
                                     exec_log="二进制未找到，已清除失败记录")

        self._installing.add(key)
        logs: list[str] = []
        try:
            env = await self._build_subprocess_env(descriptor)
            for raw_cmd in descriptor.uninstall_cmds:
                cmd = self._expand_placeholders(raw_cmd)
                logs.append(f"$ {cmd}")
                logger.info("[%s] 执行卸载命令: %s", key, cmd)
                returncode, output = await self._run_cmd(
                    cmd, UNINSTALL_CMD_TIMEOUT, env)
                logs.append(output.strip() or "(无输出)")
                if returncode != 0:
                    exec_log = "\n".join(logs)
                    await self._db.update_status(key, STATUS_FAILED, exec_log=exec_log)
                    return InstallResult(success=False,
                                         message=f"卸载命令执行失败 (exit {returncode}): {cmd}",
                                         exec_log=exec_log)

            invalidate_probe_cache(key)
            probe = await probe_tool(descriptor)
            exec_log = "\n".join(logs)
            if probe.found:
                logs.append(f"# probe: 卸载后仍可检测到 {probe.path}")
                exec_log = "\n".join(logs)

            await self._db.update_status(key, STATUS_UNINSTALLED,
                                         version=None, exec_log=exec_log)
            self._on_tool_uninstalled(descriptor)
            await self._notify_platform(key, STATUS_UNINSTALLED, healthy=False)
            logger.info("工具已卸载: %s", key)
            return InstallResult(success=True, message=f"{descriptor.name} 已卸载",
                                 exec_log=exec_log)

        except Exception as exc:
            logger.exception("工具卸载异常: %s", key)
            logs.append(f"[异常] {type(exc).__name__}: {exc}")
            exec_log = "\n".join(logs)
            try:
                await self._db.update_status(key, STATUS_FAILED, exec_log=exec_log)
            except Exception:
                logger.debug("写入卸载失败状态异常", exc_info=True)
            return InstallResult(success=False, message=f"卸载异常: {exc}",
                                 exec_log=exec_log)
        finally:
            self._installing.discard(key)

    # ─────────────────────────────────────────
    # 探测 / 更新检查
    # ─────────────────────────────────────────

    async def probe(self, key: str) -> ProbeResult:
        """手动触发探测（跳过缓存）。"""
        descriptor = self._registry.get(key)
        if not descriptor:
            return ProbeResult(found=False, problem="not_found",
                               detail=f"未知工具: {key}")
        invalidate_probe_cache(key)
        result = await probe_tool(descriptor,
                                  extra_dirs=self._probe_extra_dirs(descriptor))
        # 探测结果顺手校正安装记录（外部手动安装/删除的场景）。
        # 判据：installed 用于一般校正；但覆盖 STATUS_FAILED 必须 healthy=True，
        # 避免真实失败（version_too_low/permission/execution）被永久洗白；
        # 且不用 version=None 覆盖已有版本号，否则 check_update 会误判。
        try:
            record = await self._db.get(key)
            prev_status = record.status if record else None
            mark_installed = (
                result.installed
                and prev_status not in (STATUS_INSTALLED, STATUS_INSTALLING)
                and (prev_status != STATUS_FAILED or result.healthy)
            )
            if mark_installed:
                new_version = result.version or (record.version if record else None)
                await self._db.update_status(key, STATUS_INSTALLED,
                                             version=new_version)
                await self._notify_platform(key, STATUS_INSTALLED,
                                            version=new_version,
                                            healthy=result.healthy)
            elif (not result.found and record
                  and record.status == STATUS_INSTALLED):
                await self._db.update_status(key, STATUS_UNINSTALLED,
                                             exec_log=result.detail)
                await self._notify_platform(key, STATUS_UNINSTALLED, healthy=False)
        except Exception:
            logger.debug("探测后校正安装记录失败: %s", key, exc_info=True)
        return result

    async def check_update(self, key: str) -> UpdateInfo:
        """检查更新：npm view <package> version 与当前安装版本比对。"""
        descriptor = self._registry.get(key)
        if not descriptor:
            return UpdateInfo(message=f"未知工具: {key}")
        if not descriptor.package:
            return UpdateInfo(message="该工具无 npm 包，无法检查更新")

        record = await self._db.get(key)
        current = record.version if record and record.version else None
        if not current:
            probe = await probe_tool(descriptor, use_cache=True)
            current = probe.version

        latest = await self._npm_latest_version(descriptor.package)
        if not latest:
            return UpdateInfo(current_version=current, package=descriptor.package,
                              message="无法获取最新版本（npm view 失败或网络不可达）")

        has_update = bool(current) and compare_versions(latest, current) > 0
        if not current:
            message = f"未检测到已安装版本，最新版本 {latest}"
        elif has_update:
            message = f"发现新版本 {latest}（当前 {current}）"
        else:
            message = f"已是最新版本 {current}"
        return UpdateInfo(has_update=has_update, current_version=current,
                          latest_version=latest, package=descriptor.package,
                          message=message)

    async def _npm_latest_version(self, package: str) -> Optional[str]:
        """`npm view <package> version`（失败返回 None）。"""
        if not shutil.which("npm"):
            logger.debug("npm 不可用，跳过 %s 版本查询", package)
            return None
        returncode, output = await self._run_cmd(
            f"npm view {package} version", NPM_VIEW_TIMEOUT,
            await self._build_subprocess_env(None))
        if returncode != 0:
            logger.debug("npm view %s 失败 (exit %s): %s", package, returncode,
                         output.strip()[:200])
            return None
        version = output.strip().splitlines()
        return version[-1].strip() if version else None

    # ─────────────────────────────────────────
    # 环境变量
    # ─────────────────────────────────────────

    async def set_env_vars(self, key: str, env_vars: dict) -> bool:
        """保存环境变量：落库 + 写入 agent.env + 注入当前进程。"""
        descriptor = self._registry.get(key)
        cleaned = {str(k).strip(): str(v).strip()
                   for k, v in (env_vars or {}).items() if str(k).strip()}
        if not cleaned:
            return False

        allowed = set(descriptor.env_config_keys) if descriptor else set()
        rejected = [k for k in cleaned if allowed and k not in allowed]
        if rejected:
            logger.warning("工具 %s 拒绝了未声明的环境变量: %s", key, rejected)
            for k in rejected:
                cleaned.pop(k, None)
        if not cleaned:
            return False

        try:
            await self._db.update_env_vars(key, cleaned)
        except Exception:
            logger.exception("保存工具环境变量失败: %s", key)
            return False

        # 注入当前进程（后续子进程探测/调用即可继承）
        for name, value in cleaned.items():
            if value:
                os.environ[name] = value
            else:
                os.environ.pop(name, None)

        # 持久化到 agent.env（重启后仍生效）
        ok, message = await asyncio.to_thread(self._write_env_file, cleaned)
        if not ok:
            logger.warning("写入 agent.env 失败（已落库）: %s", message)

        # 注入 source 到 .profile 和 .bashrc（SSH 登录/终端自动加载）
        await asyncio.to_thread(self._inject_shell_source)

        invalidate_probe_cache(key)

        # 更新已注册的 Provider 实例的环境变量（热更新）
        if descriptor and descriptor.provider_name and self._manager:
            try:
                provider = self._manager.providers.get(descriptor.provider_name)
                if provider and hasattr(provider, '_env'):
                    # 合并更新：保留未在本次 cleaned 中的已有变量
                    current_env = getattr(provider, '_env', None) or {}
                    current_env.update(cleaned)
                    provider._env = {k: v for k, v in current_env.items() if v}
                    logger.info("Provider %s 环境变量已热更新: %s",
                                descriptor.provider_name, list(cleaned.keys()))
            except Exception:
                logger.debug("更新 Provider 环境变量失败", exc_info=True)

        logger.info("工具 %s 环境变量已更新: %s", key, ", ".join(sorted(cleaned)))
        logger.info("agent.env 已写入: %s", self._env_file_path())
        return True

    async def get_env_vars(self, key: str) -> dict:
        """读取已保存的环境变量（值脱敏由调用方决定）。"""
        record = await self._db.get(key)
        return dict(record.env_vars) if record else {}

    def _env_file_path(self) -> Path:
        """agent.env 路径（{~/.openchiip-harness}/agent.env）。"""
        configured = getattr(self._config, "env_file", None)
        if configured:
            return Path(configured)
        # 始终使用 ~/.openchiip-harness/agent.env 作为默认路径
        return Path.home() / ".openchiip-harness" / "agent.env"

    def _write_env_file(self, env_vars: dict) -> tuple[bool, str]:
        """同步写入 agent.env 中的托管段（幂等）。"""
        path = self._env_file_path()
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            existing = path.read_text(encoding="utf-8") if path.exists() else ""
        except OSError as exc:
            return False, f"读取 {path} 失败: {exc}"

        lines = existing.splitlines()
        managed: list[str] = []
        kept: list[str] = []
        inside = False
        for line in lines:
            if line.strip() == _ENV_MARK_BEGIN:
                inside = True
                continue
            if line.strip() == _ENV_MARK_END:
                inside = False
                continue
            if inside:
                managed.append(line)
                continue
            kept.append(line)

        # 合并托管段已有配置
        merged: dict[str, str] = {}
        for line in managed:
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            if "=" in line:
                name, _, value = line.partition("=")
                merged[name.strip().lstrip("export ").strip()] = value.strip()
        merged.update({k: v for k, v in env_vars.items()})

        block = [_ENV_MARK_BEGIN]
        block += [f"{name}={value}" for name, value in sorted(merged.items())
                  if value]
        block.append(_ENV_MARK_END)

        content = "\n".join(kept).rstrip("\n")
        content = (content + "\n\n" if content else "") + "\n".join(block) + "\n"
        try:
            path.write_text(content, encoding="utf-8")
            os.chmod(path, 0o600)
        except OSError as exc:
            return False, f"写入 {path} 失败: {exc}"
        return True, str(path)

    def _inject_shell_source(self) -> None:
        """在 .profile 和 .bashrc 中注入 source agent.env（复用平台侧逻辑）。

        注入后，SSH 登录或打开终端时环境变量会自动加载。
        """
        env_file = self._env_file_path()
        source_line = f"set -a; . {env_file}; set +a"
        home = Path.home()

        # 1) .profile — login shell（SSH / su - / bash -l）
        profile = home / ".profile"
        try:
            profile_content = profile.read_text(encoding="utf-8") if profile.exists() else ""
            if source_line not in profile_content:
                with open(profile, "a", encoding="utf-8") as f:
                    f.write(f"\n{source_line}\n")
                logger.info("已注入 source 到 .profile")
        except OSError as exc:
            logger.debug("写入 .profile 失败: %s", exc)

        # 2) .bashrc — 交互式非 login shell（终端、bash -i 等）
        bashrc = home / ".bashrc"
        try:
            bashrc_content = bashrc.read_text(encoding="utf-8") if bashrc.exists() else ""
            if source_line not in bashrc_content:
                # 在 'case $-' 守卫行之前插入；若无守卫则追加到末尾
                if "case $-" in bashrc_content:
                    bashrc_content = bashrc_content.replace(
                        "case $-",
                        f"{source_line}\ncase $-",
                        1
                    )
                    bashrc.write_text(bashrc_content, encoding="utf-8")
                else:
                    with open(bashrc, "a", encoding="utf-8") as f:
                        f.write(f"\n{source_line}\n")
                logger.info("已注入 source 到 .bashrc")
        except OSError as exc:
            logger.debug("写入 .bashrc 失败: %s", exc)

    # ─────────────────────────────────────────
    # 启用 / 禁用
    # ─────────────────────────────────────────

    async def enable(self, key: str) -> bool:
        """启用工具 → 热注册对应 Provider。"""
        descriptor = self._registry.get(key)
        if not descriptor:
            return False
        await self._db.update_enabled(key, True)
        probe = await probe_tool(descriptor, use_cache=True,
                                 extra_dirs=self._probe_extra_dirs(descriptor))
        # 热注册条件收紧：installed 且非真实失败类 problem（permission_denied/
        # execution_error/version_too_low/windows_store_alias）才注册 Provider，
        # 避免把目录/不健康路径误注册为可用 Provider；version_unverified（需配置
        # token）仍允许注册，用户补齐环境变量后即可用。
        if probe.installed and probe.problem not in _REAL_FAILURE_PROBLEMS:
            self._on_tool_installed(descriptor)
        else:
            logger.info("工具 %s 已启用，但探测未达可注册条件（installed=%s problem=%s），"
                        "Provider 未注册", key, probe.installed, probe.problem)
        await self._notify_platform(key, STATUS_INSTALLED,
                                    version=probe.version, healthy=probe.healthy)
        return True

    async def disable(self, key: str) -> bool:
        """禁用工具 → 热注销对应 Provider。"""
        descriptor = self._registry.get(key)
        if not descriptor:
            return False
        await self._db.update_enabled(key, False)
        self._on_tool_uninstalled(descriptor)
        logger.info("工具已禁用: %s", key)
        record = await self._db.get(key)
        await self._notify_platform(
            key, record.status if record else STATUS_INSTALLED, healthy=False)
        return True

    # ─────────────────────────────────────────
    # 平台协同
    # ─────────────────────────────────────────

    def _tools_json_path(self) -> Path:
        """平台下发的 tools.json 路径。"""
        configured = getattr(self._config, "tools_file", None)
        if configured:
            return Path(configured)
        return Path.home() / ".openchiip-harness" / "tools.json"

    async def reload_platform_tools(self) -> dict:
        """重新读取 tools.json，合并平台安装记录。

        平台下发条目会：
        1. 注册/覆盖 ToolDescriptor（key 未知时按条目新建）
        2. 写入安装记录（source=platform|docker-preinstall）
        """
        path = self._tools_json_path()
        summary = {"path": str(path), "registered": 0, "installed": 0,
                   "skipped": 0, "errors": []}

        if not path.exists():
            summary["errors"].append(f"tools.json 不存在: {path}")
            logger.info("平台 tools.json 不存在: %s", path)
            return summary

        try:
            raw = await asyncio.to_thread(path.read_text, "utf-8")
            data = json.loads(raw or "{}")
        except (OSError, ValueError) as exc:
            summary["errors"].append(f"解析失败: {exc}")
            logger.warning("解析 tools.json 失败: %s", exc)
            return summary

        entries = data.get("tools") if isinstance(data, dict) else data
        if not isinstance(entries, list):
            summary["errors"].append("tools.json 格式应为列表或 {\"tools\": [...]}")
            return summary

        for entry in entries:
            if not isinstance(entry, dict):
                summary["skipped"] += 1
                continue
            key = str(entry.get("key") or entry.get("name") or "").strip()
            if not key:
                summary["skipped"] += 1
                continue
            try:
                descriptor = self._descriptor_from_entry(entry, key)
                self._registry.register(descriptor)
                summary["registered"] += 1

                status = str(entry.get("status") or "").strip()
                source = str(entry.get("source") or SOURCE_PLATFORM).strip()
                if source not in (SOURCE_PLATFORM, SOURCE_DOCKER, SOURCE_LOCAL):
                    source = SOURCE_PLATFORM
                record = await self._db.get(key)
                version = entry.get("version") or (record.version if record else None)
                if status in (STATUS_INSTALLED, STATUS_INSTALLING, STATUS_FAILED,
                              STATUS_UNINSTALLED):
                    await self._db.update_status(key, status, version=version,
                                                 source=source)
                elif status:
                    # 平台自定义状态：保留记录但不覆盖本地判定
                    await self._db.upsert(ToolInstallation(
                        key=key, status=STATUS_NOT_INSTALLED, version=version,
                        source=source))
                if status == STATUS_INSTALLED:
                    summary["installed"] += 1
                    invalidate_probe_cache(key)
                    # 触发 Provider 热注册：平台下发的已安装工具立即可用
                    record_after = await self._db.get(key)
                    if record_after is None or record_after.enabled:
                        self._on_tool_installed(descriptor)
            except Exception as exc:
                logger.warning("合并平台工具条目失败 %s: %s", key, exc)
                summary["errors"].append(f"{key}: {exc}")

        logger.info("平台 tools.json 已加载: %s", summary)
        return summary

    def _descriptor_from_entry(self, entry: dict, key: str) -> ToolDescriptor:
        """把平台条目转为 ToolDescriptor（已存在的内置项仅做增量补充）。"""
        existing = self._registry.get(key)
        base = existing.to_dict() if existing else {}
        overrides = {k: v for k, v in entry.items() if v is not None}

        # 平台条目的 check_cmd 可能是 SSH 包装命令（sudo -u {linux_user} ...
        # bash -lc "{home}/.local/bin/qodercli --version"），执行主体与运行时
        # daemon 不同，覆盖后会让探测退化。此类 check_cmd 直接忽略，保留运行时
        # 内置 descriptor 自己的 check_cmd / probe 语义（与 Lee 的 _version_args
        # 严格判据协同）。
        if _is_platform_ssh_check_cmd(overrides.get("check_cmd")):
            logger.debug("忽略平台 SSH 包装 check_cmd（%s）: %s",
                         key, overrides.get("check_cmd"))
            overrides.pop("check_cmd", None)

        # probe_cmd 同样需要过滤：它走 _version_args 的“可信分支”（不做 SSH-marker
        # 过滤），若平台下发 SSH 包装式 probe_cmd 仍会让探测退化（无命令注入风险，
        # 因 create_subprocess_exec 无 shell，但会误判）。命中则忽略，回退到内置
        # base 的 probe_cmd（与 check_cmd 处理一致）。
        if _is_platform_ssh_check_cmd(overrides.get("probe_cmd")):
            logger.debug("忽略平台 SSH 包装 probe_cmd（%s）: %s",
                         key, overrides.get("probe_cmd"))
            overrides.pop("probe_cmd", None)

        merged = {**base, **overrides}

        def _as_list(value, fallback) -> list:
            if isinstance(value, list):
                return value
            if isinstance(value, str) and value.strip():
                return [value.strip()]
            return list(fallback or [])

        return ToolDescriptor(
            key=key,
            name=str(merged.get("name") or key),
            description=str(merged.get("description") or ""),
            category=str(merged.get("category") or "ai-agent"),
            icon=str(merged.get("icon") or "Wrench"),
            binary=str(merged.get("binary") or ""),
            package=merged.get("package"),
            install_cmds=_as_list(merged.get("install_cmds"), []),
            uninstall_cmds=_as_list(merged.get("uninstall_cmds"), []),
            check_cmd=merged.get("check_cmd"),
            min_version=merged.get("min_version"),
            env_config_keys=_as_list(merged.get("env_config_keys"), []),
            # 透传可选版本列表与探测定制项，避免 reload/register 覆盖后被静默抹掉
            versions=_as_list(merged.get("versions"), []),
            probe_cmd=merged.get("probe_cmd"),
            probe_timeout=merged.get("probe_timeout"),
            probe_retries=merged.get("probe_retries"),
            provider_name=merged.get("provider_name"),
            install_hint=merged.get("install_hint"),
            is_builtin=bool(merged.get("is_builtin", False)),
            sort_order=int(merged.get("sort_order") or (existing.sort_order if existing else 100)),
        )

    # ─────────────────────────────────────────
    # Provider 联动回调
    # ─────────────────────────────────────────

    def _on_tool_installed(self, descriptor: ToolDescriptor) -> None:
        """安装成功/启用后的回调：热注册对应 SubagentProvider。"""
        if not self._manager or not descriptor.provider_name:
            return
        if self._provider_registered(descriptor):
            logger.debug("Provider 已注册，跳过: %s", descriptor.provider_name)
            return
        provider = self._build_provider(descriptor)
        if provider is None:
            return
        try:
            self._manager.register(provider)
            logger.info("Provider 热注册成功: %s (工具 %s)",
                        descriptor.provider_name, descriptor.key)
        except Exception:
            logger.exception("Provider 热注册失败: %s", descriptor.provider_name)

    def _on_tool_uninstalled(self, descriptor: ToolDescriptor) -> None:
        """卸载/禁用后的回调：热注销对应 SubagentProvider。"""
        if not self._manager or not descriptor.provider_name:
            return
        try:
            self._manager.unregister(descriptor.provider_name)
            logger.info("Provider 热注销: %s (工具 %s)",
                        descriptor.provider_name, descriptor.key)
        except Exception:
            logger.exception("Provider 热注销失败: %s", descriptor.provider_name)

    def _build_provider(self, descriptor: ToolDescriptor):
        """按 provider_name 构造 SubagentProvider 实例（未知则返回 None）。"""
        name = descriptor.provider_name
        if not name:
            return None

        params = getattr(self._config, "params", {}) or {}
        env = self._provider_env(descriptor)

        try:
            if name == "codex":
                from .subagent import CodexSubagentProvider
                return CodexSubagentProvider(config={
                    "codex_command": descriptor.binary or params.get("codex_command", "codex"),
                    "codex_model": params.get("codex_model", "gpt-5.4"),
                    "codex_timeout": params.get("codex_timeout", 120000),
                    "codex_bypass_sandbox": params.get("codex_bypass_sandbox", True),
                    "env": env,
                })
            if name == "qoder":
                from .subagent import QoderSubagentProvider
                return QoderSubagentProvider(config={
                    "qoder_command": descriptor.binary or params.get("qoder_command", "qodercli"),
                    "qoder_timeout": params.get("qoder_timeout", 120000),
                    "qoder_yolo": params.get("qoder_yolo", True),
                    "env": env,
                })
            if name == "claude-code":
                from .subagent import ClaudeCodeSubagentProvider
                return ClaudeCodeSubagentProvider(config={
                    "claude_code_command": descriptor.binary or params.get("claude_code_command", "claude"),
                    "claude_code_model": params.get("claude_code_model", "claude-sonnet-4-20250514"),
                    "claude_code_timeout": params.get("claude_code_timeout", 600),
                    "claude_code_skip_permissions": params.get("claude_code_skip_permissions", True),
                    "env": env,
                })
        except Exception:
            logger.exception("构造 Provider 失败: %s", name)
            return None

        logger.info("工具 %s 暂无对应 Provider 实现（provider_name=%s）",
                    descriptor.key, name)
        return None

    async def _provider_env_async(self, descriptor: ToolDescriptor) -> dict:
        record = await self._db.get(descriptor.key)
        return dict(record.env_vars) if record and record.env_vars else {}

    def _provider_env(self, descriptor: ToolDescriptor) -> dict:
        """同步读取已保存的环境变量（供 Provider 构造使用）。"""
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = None
        if loop is None:
            try:
                return asyncio.run(self._provider_env_async(descriptor))
            except Exception:
                return {}
        # 事件循环内：从进程环境兜底（set_env_vars 已注入 os.environ）
        return {k: os.environ.get(k, "") for k in descriptor.env_config_keys
                if os.environ.get(k)}

    # ─────────────────────────────────────────
    # 统一视图
    # ─────────────────────────────────────────

    async def list_tools_view(self) -> list[dict]:
        """三来源合并的统一工具列表：注册表描述符 + MCP 工具 + 安装记录。"""
        records = await self._db.get_map()
        descriptors = self._registry.list_all()
        probes = await self._probe_known(descriptors, records)

        items = [self._build_view(d, records.get(d.key), probes.get(d.key))
                 for d in descriptors]
        items += self._mcp_view(records)
        return items

    async def get_tool_view(self, key: str) -> Optional[dict]:
        """单个工具的统一视图（含实时探测结果）。"""
        descriptor = self._registry.get(key)
        record = await self._db.get(key)
        if descriptor is None:
            for item in self._mcp_view({key: record} if record else {}):
                if item["key"] == key:
                    return item
            return None
        probe = await probe_tool(
            descriptor, use_cache=True,
            extra_dirs=self._probe_extra_dirs(descriptor))
        view = self._build_view(descriptor, record, probe)
        view["probe"] = probe.to_dict()
        view["install_cmds"] = list(descriptor.install_cmds)
        view["uninstall_cmds"] = list(descriptor.uninstall_cmds)
        view["package"] = descriptor.package
        view["binary"] = descriptor.binary
        view["min_version"] = descriptor.min_version
        view["provider_name"] = descriptor.provider_name
        view["is_builtin"] = descriptor.is_builtin
        view["sort_order"] = descriptor.sort_order
        view["exec_log"] = record.exec_log if record else None
        view["installed_at"] = record.installed_at if record else None
        view["updated_at"] = record.updated_at if record else None
        view["installing"] = key in self._installing
        return view

    async def _probe_known(self, descriptors: list,
                           records: dict) -> dict[str, ProbeResult]:
        """批量探测有 binary 的工具（带缓存，避免列表接口卡顿）。"""
        targets = [d for d in descriptors if d.binary]
        if not targets:
            return {}
        extra_dirs_map = {d.key: self._probe_extra_dirs(d) for d in targets}
        return await probe_tools(targets, use_cache=True,
                                 extra_dirs_map=extra_dirs_map)

    def _build_view(self, descriptor: ToolDescriptor,
                    record: Optional[ToolInstallation],
                    probe: Optional[ProbeResult]) -> dict:
        """组装单个工具的统一视图。"""
        version = (probe.version if probe and probe.version else None) \
            or (record.version if record else None)
        binary_path = probe.path if probe and probe.path else None

        # 真实失败类 problem（version_too_low / windows_store_alias /
        # permission_denied / execution_error）：即便 installed=True 也呈现 failed，
        # 保住前端 ToolCard 的失败原因面板与"重新安装"入口。
        real_failure = bool(probe and probe.problem in _REAL_FAILURE_PROBLEMS)

        if record and record.status in (STATUS_INSTALLING, STATUS_FAILED,
                                        STATUS_UNINSTALLED, STATUS_INSTALLED):
            status = record.status
        elif probe and probe.installed:
            # installed（二进制可定位）即视为已安装；healthy 另行单独映射，
            # version_unverified 这类告警保持 status=installed + healthy=False
            status = STATUS_INSTALLED
        else:
            status = STATUS_NOT_INSTALLED

        if real_failure and status != STATUS_INSTALLING:
            # 真实失败优先呈现 failed（覆盖 DB 里可能残留的 installed/uninstalled）
            status = STATUS_FAILED
        # installed 且非真实失败 → 以真实状态覆盖历史 uninstalled/not_installed。
        # 注意：不覆盖 DB 的 STATUS_FAILED，避免把失败记录洗白为"已安装"。
        elif probe and probe.installed and status in (STATUS_UNINSTALLED,
                                                      STATUS_NOT_INSTALLED):
            status = STATUS_INSTALLED
        # 记录为已安装但二进制已消失（手动删除/镜像变更）
        elif (probe is not None and not probe.found
              and status == STATUS_INSTALLED):
            status = STATUS_UNINSTALLED

        enabled = bool(record.enabled) if record else True
        env_configured = self._env_configured(descriptor, record)

        # 版本过低检测：已安装但低于 min_version 时标记为 outdated
        outdated = False
        if version and descriptor.min_version:
            from .tool_probe import compare_versions
            try:
                outdated = compare_versions(version, descriptor.min_version) < 0
            except Exception:
                pass

        return {
            "key": descriptor.key,
            "name": descriptor.name,
            "description": descriptor.description,
            "category": descriptor.category,
            "icon": descriptor.icon,
            "status": status,
            "enabled": enabled,
            "healthy": bool(probe and probe.healthy and enabled),
            "version": version,
            "binary_path": binary_path,
            "provider_registered": self._provider_registered(descriptor),
            "env_config_keys": list(descriptor.env_config_keys),
            "env_configured": env_configured,
            "install_hint": descriptor.install_hint,
            "can_auto_install": descriptor.can_auto_install or bool(descriptor.install_cmds and descriptor.versions),
            "versions": list(descriptor.versions),
            "min_version": descriptor.min_version,
            "outdated": outdated,
            "source": record.source if record else SOURCE_LOCAL,
            "problem": probe.problem if probe else None,
            "problem_detail": probe.detail if probe else None,
            "installing": descriptor.key in self._installing,
            # 兼容旧版前端 Tools.tsx 的 methods 字段
            "methods": [],
        }

    def _env_configured(self, descriptor: ToolDescriptor,
                        record: Optional[ToolInstallation]) -> dict:
        """各环境变量是否已配置（不返回明文值）。"""
        saved = record.env_vars if record and record.env_vars else {}
        return {
            key: bool(saved.get(key) or os.environ.get(key))
            for key in descriptor.env_config_keys
        }

    def _provider_registered(self, descriptor: ToolDescriptor) -> bool:
        if not self._manager or not descriptor.provider_name:
            return False
        try:
            return descriptor.provider_name in self._manager.providers
        except Exception:
            return False

    def _mcp_view(self, records: dict) -> list[dict]:
        """把既有 MCP 工具映射为统一视图条目（category=mcp）。"""
        if not self._mcp_tools:
            return []
        try:
            raw_tools = self._mcp_tools.list_tools()
        except Exception:
            logger.debug("读取 MCP 工具列表失败", exc_info=True)
            return []

        known = set(self._registry.keys())
        items: list[dict] = []
        for tool in raw_tools or []:
            if not isinstance(tool, dict):
                continue
            key = str(tool.get("key") or tool.get("name") or "").strip()
            if not key or key in known:
                continue
            record = records.get(key)
            items.append({
                "key": key,
                "name": str(tool.get("name") or key),
                "description": str(tool.get("description") or ""),
                "category": str(tool.get("category") or "mcp"),
                "icon": "Plug",
                "status": record.status if record else STATUS_INSTALLED,
                "enabled": bool(record.enabled) if record else True,
                "healthy": True,
                "version": (record.version if record else None)
                or str(tool.get("version") or ""),
                "binary_path": tool.get("command") or None,
                "provider_registered": False,
                "env_config_keys": [],
                "env_configured": {},
                "install_hint": None,
                "can_auto_install": False,
                "source": record.source if record else SOURCE_LOCAL,
                "problem": None,
                "problem_detail": None,
                "installing": key in self._installing,
                "mcp": True,
                "methods": list(tool.get("methods") or []),
            })
        return items

    # ─────────────────────────────────────────
    # 内部工具
    # ─────────────────────────────────────────

    def _expand_placeholders(self, cmd: str, version: str = None) -> str:
        """占位符替换：{home} → ~/.openchiip-harness，{user} → $USER，{version} → 版本号。"""
        harness_home = os.path.expanduser("~/.openchiip-harness")
        result = (cmd or "").replace("{home}", harness_home) \
                        .replace("{user}", os.getenv("USER") or os.getenv("USERNAME") or "")
        if version:
            result = result.replace("{version}", version)
        return result

    def _install_prefix_dirs(self, descriptor: ToolDescriptor) -> list[str]:
        """从安装命令中解析自定义 prefix（如 `npm install -g --prefix DIR`）。

        这类安装会把可执行文件放到 PATH 之外的目录，安装后探测需额外搜索
        DIR/bin，否则会误报「安装命令成功但工具不可用」。
        """
        dirs: list[str] = []
        for raw_cmd in descriptor.install_cmds:
            cmd = self._expand_placeholders(raw_cmd)
            try:
                tokens = shlex.split(cmd)
            except ValueError:
                tokens = cmd.split()
            for index, token in enumerate(tokens):
                value = None
                if token == "--prefix" and index + 1 < len(tokens):
                    value = tokens[index + 1]
                elif token.startswith("--prefix="):
                    value = token.split("=", 1)[1]
                if not value:
                    continue
                root = os.path.expanduser(value)
                dirs.append(root if os.name == "nt" else os.path.join(root, "bin"))

        npm_prefix = os.environ.get("NPM_CONFIG_PREFIX")
        if npm_prefix:
            root = os.path.expanduser(npm_prefix)
            dirs.append(root if os.name == "nt" else os.path.join(root, "bin"))
        return dirs

    def _check_prerequisites(self, descriptor: ToolDescriptor,
                              env: Optional[dict] = None) -> list[str]:
        """检测安装命令所需的前置可执行程序（npm/node/curl 等）。

        忽略 shell 内建命令与显式路径，避免将 `exit`/`true`/`./install.sh`
        误判为缺失依赖。

        Args:
            descriptor: 工具描述符
            env: 可选的子进程环境（使用其 PATH 进行检测，而非 daemon 进程的 PATH）
        """
        required: set = set()
        for raw_cmd in descriptor.install_cmds:
            cmd = self._expand_placeholders(raw_cmd).strip()
            if not cmd:
                continue
            if any(sep in cmd for sep in ("|", "&&", "||", ";")):
                # 管道/串联命令：检测其中出现的常见程序
                for token in _COMMON_PROGRAMS:
                    if _contains_word(cmd, token):
                        required.add(token)
                continue
            program = _leading_program(cmd)
            if program:
                required.add(program)

        # npm/npx 依赖 node 运行时
        if required & {"npm", "npx"}:
            required.add("node")

        return sorted(name for name in required
                      if name not in _SHELL_BUILTINS
                      and not name.startswith(("/", "./", "../"))
                      and not shutil.which(name, path=env.get("PATH") if env else None))

    @staticmethod
    def _prerequisite_hint(missing: list[str]) -> str:
        if "npm" in missing or "node" in missing:
            return ("缺少 Node.js/npm，请先安装 Node.js 18+："
                    "https://nodejs.org/ （或使用 nvm: "
                    "curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.39.7/install.sh | bash）")
        return f"请先安装缺失的依赖: {', '.join(missing)}"

    @staticmethod
    def _install_failure_hint(descriptor: ToolDescriptor, output: str) -> Optional[str]:
        """根据失败输出给出可执行的建议。"""
        low = (output or "").lower()
        if "eacces" in low or "permission denied" in low:
            return ("npm 全局目录无写权限，建议配置用户级前缀："
                    "npm config set prefix ~/.npm-global 并将 ~/.npm-global/bin 加入 PATH")
        if "enotfound" in low or "network" in low or "timeout" in low:
            return "网络不可达，可切换 npm 镜像: npm config set registry https://registry.npmmirror.com"
        if "npm" in low and "not found" in low:
            return "未检测到 npm，请先安装 Node.js 18+"
        return descriptor.install_hint

    def _extra_path_dirs(self) -> list[str]:
        """子进程与探测共用的 PATH 补齐目录（消除"安装用 A 环境、探测用 B 环境"偏差）。

        与 `_build_subprocess_env` 拼接进 PATH 的目录完全一致：用户级 bin、
        npm 全局 prefix、nvm 各版本 bin 等——daemon 自身 PATH 常缺这些目录，
        安装子进程能写进去、探测却读不到，正是漏检根因之一。
        """
        extra: list[str] = []
        home = os.path.expanduser("~")
        for candidate in (os.path.join(home, ".local", "bin"),
                          "/usr/local/bin", "/opt/homebrew/bin",
                          os.path.join(home, ".npm-global", "bin"),
                          os.path.join(home, ".volta", "bin"),
                          os.path.join(home, ".bun", "bin")):
            if os.path.isdir(candidate):
                extra.append(candidate)
        npm_prefix = os.environ.get("NPM_CONFIG_PREFIX")
        if npm_prefix:
            extra.append(os.path.join(npm_prefix, "bin"))
        # nvm 安装的 Node.js 版本（~/.nvm/versions/node/vXX.Y.Z/bin）
        nvm_base = os.path.join(home, ".nvm", "versions", "node")
        if os.path.isdir(nvm_base):
            for entry in sorted(os.listdir(nvm_base), reverse=True):
                bin_dir = os.path.join(nvm_base, entry, "bin")
                if os.path.isdir(bin_dir):
                    extra.append(bin_dir)
        return extra

    def _probe_extra_dirs(self, descriptor: ToolDescriptor) -> list[str]:
        """探测用的额外搜索目录：安装 prefix 目录 + 子进程补齐的 PATH 目录（去重保序）。

        prefix 目录（刚安装到的位置）优先于补齐的 PATH 目录，一并交给 probe_tool
        的 extra_dirs，使安装子进程与探测共用同一套 PATH 来源。
        """
        dirs = list(self._install_prefix_dirs(descriptor)) + self._extra_path_dirs()
        seen: set = set()
        result: list[str] = []
        for d in dirs:
            if not d:
                continue
            norm = os.path.normpath(os.path.expanduser(d))
            if norm in seen:
                continue
            seen.add(norm)
            result.append(d)
        return result

    async def _build_subprocess_env(self, descriptor: Optional[ToolDescriptor]) -> dict:
        """构造子进程环境：补齐 PATH 回退目录 + 注入已配置的工具环境变量。"""
        env = dict(os.environ)

        extra = self._extra_path_dirs()
        if extra:
            env["PATH"] = os.pathsep.join(extra + [env.get("PATH", "")])

        # 工具自身的环境变量（如 OPENAI_API_KEY）
        if descriptor is not None:
            try:
                record = await self._db.get(descriptor.key)
                for name, value in (record.env_vars if record else {}).items():
                    if value:
                        env[name] = value
            except Exception:
                logger.debug("读取工具环境变量失败: %s",
                             descriptor.key, exc_info=True)
        return env

    async def _run_cmd(self, cmd: str, timeout: float, env: dict,
                       cwd: Optional[str] = None) -> tuple[int, str]:
        """执行 shell 命令（合并 stderr，超时保护，输出限长）。"""
        try:
            proc = await asyncio.create_subprocess_shell(
                cmd,
                stdin=asyncio.subprocess.DEVNULL,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.STDOUT,
                cwd=cwd,
                env=env,
            )
        except OSError as exc:
            return -1, f"[启动失败] {type(exc).__name__}: {exc}"

        try:
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=timeout)
        except asyncio.TimeoutError:
            try:
                proc.kill()
            except ProcessLookupError:
                pass
            except Exception:
                logger.debug("终止安装子进程失败", exc_info=True)
            try:
                await asyncio.wait_for(proc.wait(), timeout=5)
            except (asyncio.TimeoutError, Exception):
                pass
            return -1, f"[超时] 命令在 {timeout:.0f}s 内未完成"

        text = (stdout or b"").decode("utf-8", errors="replace")
        if len(text) > 20000:
            text = text[:8000] + "\n...(输出截断)...\n" + text[-8000:]
        return proc.returncode or 0, text


def build_tool_installer(app) -> Optional[ToolInstaller]:
    """从 AgentApp 组装 ToolInstaller（含 ToolDatabase 初始化）。

    由 server/app.py 在 lifespan 中调用，失败时返回 None（不影响主流程）。
    """
    try:
        from .tool_registry import ToolRegistry

        config = getattr(app, "config", None)
        db_path = Path(getattr(config, "runtime_home",
                               str(Path.home() / ".openchiip-harness" / "data"))) / "tools.db"
        tool_db = ToolDatabase(str(db_path))
        registry = ToolRegistry()
        installer = ToolInstaller(
            registry=registry,
            db=tool_db,
            subagent_manager=getattr(app, "subagent_manager", None),
            config=config,
            mcp_tools=getattr(app, "tools", None),
            ws_client=getattr(app, "ws_client", None),
        )
        return installer
    except Exception:
        logger.exception("组装 ToolInstaller 失败")
        return None
